import (
	"strings"
	"testing"
)

func TestReviewTruncateMessage(t *testing.T) {
	if noteLengthLimit != 1024 {
		t.Fatalf("noteLengthLimit=%d", noteLengthLimit)
	}
	exact := strings.Repeat("a", 1024)
	if got := truncateMessage(exact); got != exact {
		t.Fatalf("exact-length message changed: len=%d", len(got))
	}
	long := strings.Repeat("b", 1025)
