	if len(got) != 1024 || !strings.HasSuffix(got, " ...") {
		t.Fatalf("long message: len=%d suffix=%q", len(got), got[len(got)-4:])
	}
	t.Logf("exact=%d long-in=%d long-out=%d", len(truncateMessage(exact)), len(long), len(got))
}
